9	/**
10	 * Rejects a create whose city already contains 50 or more owners. The city is compared
11	 * case-insensitively. Runs before the owner is saved, so the count excludes the owner being
12	 * created; a full city is rejected 409 via {@link CityAtCapacityException}.
13	 */
14	public class EnsureCityCapacity {
15	
16	    /** Maximum number of owners a single city may contain. */
17	    private static final int CITY_CAPACITY = 50;
18	
19	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
20	            throws CityAtCapacityException {
21	        String city = request.getCity();
22	        int count = 0;
23	        for (Owner existing : ownerRepository.findAll()) {
24	            if (city.equalsIgnoreCase(existing.getCity())) {
25	                count++;
26	            }
27	        }
28	        if (count >= CITY_CAPACITY) {
29	            throw new CityAtCapacityException(city, count);
30	        }
31	    }
32	}
